        $this->classConstSupportedHints = [
            'array' => true,
            'bool' => true,
            'float' => true,
            'int' => true,
            'iterable' => true,
            'mixed' => true,
            'null' => true,
            'object' => true,
            'parent' => true,
            'self' => true,
            'string' => true,
            'static' => true,
        ];
        $this->classPropertySupportedHints = [
            'array' => true,
            'bool' => true,
            'float' => true,
            'int' => true,
            'iterable' => true,
            'mixed' => true,
            'null' => true,
            'object' => true,
            'parent' => true,
            'self' => true,
            'static' => true,
            'string' => true,
