        while ($tokens[$prevIndex]->isGivenKind([CT::T_NAMESPACE_OPERATOR, T_NS_SEPARATOR, T_STRING])) {
            $prevIndex = $tokens->getPrevMeaningfulToken($prevIndex);
            if (null === $prevIndex) {
                return false;
            }
        }

        if ($this->constantInvocationHasForbiddenResolvedPrevToken($prevIndex)) {
            return false;
        }

        if ($this->isFunctionReferenceParameter($prevIndex, $nextIndex)) {
            return false;
        }

        if ($this->isImportListConstantLookalike($prevIndex)) {
            return false;
        }

        if ($this->isQuotedStringArrayIndex($prevIndex, $nextIndex)) {
            return false;
        }

        if (AttributeAnalyzer::isAttribute($tokens, $index)) {
            return false;
        }

        if ($this->belongsToGotoLabel($nextIndex)) {
            return false;
        }

        return !$this->isNonCapturingCatchType($prevIndex);
    }

    private function constantInvocationHasForbiddenNextToken(int $nextIndex): bool
    {
        $tokens = $this->constantInvocationTokens;
        if (null === $tokens) {
            return true;
        }

        return $tokens[$nextIndex]->equalsAny(['(', '{'])
            || $tokens[$nextIndex]->isGivenKind([
                T_AS,
                T_DOUBLE_COLON,
                T_ELLIPSIS,
                T_NS_SEPARATOR,
                CT::T_RETURN_REF,
                CT::T_TYPE_ALTERNATION,
                CT::T_TYPE_INTERSECTION,
                T_VARIABLE,
            ]);
    }

    private function constantInvocationHasForbiddenPrevToken(int $prevIndex): bool
    {
        $tokens = $this->constantInvocationTokens;
        if (null === $tokens) {
            return true;
        }

        return $tokens[$prevIndex]->isGivenKind([
            T_AS,
            T_CLASS,
            T_CONST,
            T_DOUBLE_COLON,
            T_FUNCTION,
            T_GOTO,
            CT::T_GROUP_IMPORT_BRACE_OPEN,
            T_INTERFACE,
            T_TRAIT,
            CT::T_TYPE_COLON,
            CT::T_TYPE_ALTERNATION,
            CT::T_TYPE_INTERSECTION,
        ]) || $tokens[$prevIndex]->isObjectOperator();
    }

    private function constantInvocationHasForbiddenResolvedPrevToken(int $prevIndex): bool
    {
        $tokens = $this->constantInvocationTokens;
        if (null === $tokens) {
            return true;
        }

        return $tokens[$prevIndex]->isGivenKind([
            CT::T_CONST_IMPORT,
            T_EXTENDS,
            CT::T_FUNCTION_IMPORT,
            T_IMPLEMENTS,
            T_INSTANCEOF,
            T_INSTEADOF,
            T_NAMESPACE,
            T_NEW,
            CT::T_NULLABLE_TYPE,
            CT::T_TYPE_COLON,
            T_USE,
            CT::T_USE_TRAIT,
            CT::T_TYPE_INTERSECTION,
            CT::T_TYPE_ALTERNATION,
            T_CONST,
            CT::T_DISJUNCTIVE_NORMAL_FORM_TYPE_PARENTHESIS_CLOSE,
        ]);
    }

    private function isFunctionReferenceParameter(int $prevIndex, int $nextIndex): bool
    {
        $tokens = $this->constantInvocationTokens;
        if (null === $tokens) {
            return false;
        }

        $nextNextIndex = $tokens->getNextMeaningfulToken($nextIndex);
        if (!$tokens[$nextIndex]->equals('&') || null === $nextNextIndex || !$tokens[$nextNextIndex]->isGivenKind(T_VARIABLE)) {
            return false;
        }

        $checkIndex = $tokens->getPrevTokenOfKind($prevIndex, [';', '{', '}', [T_FUNCTION], [T_OPEN_TAG], [T_OPEN_TAG_WITH_ECHO]]);

        return null !== $checkIndex && $tokens[$checkIndex]->isGivenKind(T_FUNCTION);
    }

    private function isImportListConstantLookalike(int $prevIndex): bool
    {
        $tokens = $this->constantInvocationTokens;
        if (null === $tokens || !$tokens[$prevIndex]->equals(',')) {
            return false;
        }

        $checkIndex = $prevIndex;
        while ($tokens[$checkIndex]->equalsAny([',', [T_AS], [CT::T_NAMESPACE_OPERATOR], [T_NS_SEPARATOR], [T_STRING]])) {
            $checkIndex = $tokens->getPrevMeaningfulToken($checkIndex);
            if (null === $checkIndex) {
                return false;
            }
        }

        return $tokens[$checkIndex]->isGivenKind([T_EXTENDS, CT::T_GROUP_IMPORT_BRACE_OPEN, T_IMPLEMENTS, T_USE, CT::T_USE_TRAIT]);
    }

    private function isQuotedStringArrayIndex(int $prevIndex, int $nextIndex): bool
    {
        $tokens = $this->constantInvocationTokens;
        if (null === $tokens || !$tokens[$prevIndex]->equals('[') || !$tokens[$nextIndex]->equals(']')) {
            return false;
        }

        $checkTokenIndex = $tokens->getNextMeaningfulToken($nextIndex);
        if (null === $checkTokenIndex) {
            return false;
        }

        $checkToken = $tokens[$checkTokenIndex];

        return $checkToken->equals('"') || $checkToken->isGivenKind([T_CURLY_OPEN, T_DOLLAR_OPEN_CURLY_BRACES, T_ENCAPSED_AND_WHITESPACE, T_VARIABLE]);
    }

    private function belongsToGotoLabel(int $nextIndex): bool
    {
        $tokens = $this->constantInvocationTokens;
        if (null === $tokens || !$tokens[$nextIndex]->equals(':')) {
            return false;
        }

        if (null === $this->gotoLabelAnalyzer) {
            $this->gotoLabelAnalyzer = new GotoLabelAnalyzer();
        }

        return $this->gotoLabelAnalyzer->belongsToGoToLabel($tokens, $nextIndex);
    }

    private function isNonCapturingCatchType(int $prevIndex): bool
    {
        $tokens = $this->constantInvocationTokens;
        if (null === $tokens) {
            return false;
        }

        while ($tokens[$prevIndex]->isGivenKind([CT::T_NAMESPACE_OPERATOR, T_NS_SEPARATOR, T_STRING, CT::T_TYPE_ALTERNATION])) {
            $prevIndex = $tokens->getPrevMeaningfulToken($prevIndex);
            if (null === $prevIndex) {
                return false;
            }
        }

        if (!$tokens[$prevIndex]->equals('(')) {
            return false;
        }

        $prevPrevIndex = $tokens->getPrevMeaningfulToken($prevIndex);

        return null !== $prevPrevIndex && $tokens[$prevPrevIndex]->isGivenKind(T_CATCH);
    }

    public function applyMagicMethodCasing(Tokens $tokens): void
    {
        $this->magicCasingTokens = $tokens;
        $this->magicMethodClassDepth = 0;
        $this->ensureMagicMethodNames();

        $tokenCount = \count($tokens);
        for ($index = 1; $index < $tokenCount - 2; ++$index) {
            $index = $this->advanceMagicMethodClassContext($index);
            if (null === $this->magicCasingTokens) {
                return;
            }

            if (!$tokens[$index]->isGivenKind(T_STRING)) {
                continue;
            }

            $this->maybeFixMagicMethodName($index);
        }
    }

    private function ensureMagicMethodNames(): void
    {
        if ([] !== $this->magicMethodNames && null !== $this->magicCasingTokens) {
            return;
        }

        $this->magicMethodNames = [
            '__call' => '__call',
            '__callstatic' => '__callStatic',
            '__clone' => '__clone',
            '__construct' => '__construct',
            '__debuginfo' => '__debugInfo',
            '__destruct' => '__destruct',
            '__get' => '__get',
            '__invoke' => '__invoke',
            '__isset' => '__isset',
            '__serialize' => '__serialize',
            '__set' => '__set',
            '__set_state' => '__set_state',
            '__sleep' => '__sleep',
            '__tostring' => '__toString',
            '__unserialize' => '__unserialize',
            '__unset' => '__unset',
            '__wakeup' => '__wakeup',
        ];
    }

    private function advanceMagicMethodClassContext(int $index): int
    {
        $tokens = $this->magicCasingTokens;
        if (null === $tokens) {
            return $index;
        }

        if (0 === $this->magicMethodClassDepth && $tokens[$index]->isClassy()) {
            $this->magicMethodClassDepth = 1;
            $next = $tokens->getNextTokenOfKind($index, ['{']);

            return null === $next ? $index : $next;
        }

        if (0 !== $this->magicMethodClassDepth) {
            if ($tokens[$index]->equals('{')) {
                ++$this->magicMethodClassDepth;
            } elseif ($tokens[$index]->equals('}')) {
                --$this->magicMethodClassDepth;
            }
        }

        return $index;
    }

    private function maybeFixMagicMethodName(int $index): void
    {
        $tokens = $this->magicCasingTokens;
        if (null === $tokens) {
            return;
        }

        $content = $tokens[$index]->getContent();
        if (!str_starts_with($content, '__')) {
            return;
        }

        $name = strtolower($content);
        if (!$this->isMagicMethodName($name)) {
            return;
        }

        $nameInCorrectCasing = $this->getMagicMethodNameInCorrectCasing($name);
        if ($nameInCorrectCasing === $content) {
            return;
        }

        if ($this->isMagicFunctionSignature($index)) {
            if (0 !== $this->magicMethodClassDepth) {
                $this->setMagicMethodTokenCasing($index, $nameInCorrectCasing);
            }

            return;
        }

        if ($this->isMagicMethodCall($index)) {
            $this->setMagicMethodTokenCasing($index, $nameInCorrectCasing);

            return;
        }

        if (
            ('__callstatic' === $name || '__set_state' === $name)
            && $this->isMagicStaticMethodCall($index)
        ) {
            $this->setMagicMethodTokenCasing($index, $nameInCorrectCasing);
        }
    }

    private function isMagicFunctionSignature(int $index): bool
    {
        $tokens = $this->magicCasingTokens;
        if (null === $tokens) {
            return false;
        }

        $prevIndex = $tokens->getPrevMeaningfulToken($index);
        if (null === $prevIndex || !$tokens[$prevIndex]->isGivenKind(T_FUNCTION)) {
            return false;
        }

        $nextIndex = $tokens->getNextMeaningfulToken($index);

        return null !== $nextIndex && $tokens[$nextIndex]->equals('(');
    }

    private function isMagicMethodCall(int $index): bool
    {
        $tokens = $this->magicCasingTokens;
        if (null === $tokens) {
            return false;
        }

        $prevIndex = $tokens->getPrevMeaningfulToken($index);
        if (null === $prevIndex || !$tokens[$prevIndex]->isObjectOperator()) {
            return false;
        }

        $nextIndex = $tokens->getNextMeaningfulToken($index);

        return null !== $nextIndex && $tokens[$nextIndex]->equals('(');
    }

    private function isMagicStaticMethodCall(int $index): bool
    {
        $tokens = $this->magicCasingTokens;
        if (null === $tokens) {
            return false;
        }

        $prevIndex = $tokens->getPrevMeaningfulToken($index);
        if (null === $prevIndex || !$tokens[$prevIndex]->isGivenKind(T_DOUBLE_COLON)) {
            return false;
        }

        $nextIndex = $tokens->getNextMeaningfulToken($index);

        return null !== $nextIndex && $tokens[$nextIndex]->equals('(');
    }

    private function isMagicMethodName(string $name): bool
    {
        if (null === $this->magicCasingTokens) {
            return false;
        }

        return isset($this->magicMethodNames[$name]);
    }

    private function getMagicMethodNameInCorrectCasing(string $name): string
    {
        if (null === $this->magicCasingTokens) {
            return $name;
        }

        return $this->magicMethodNames[$name];
    }

    private function setMagicMethodTokenCasing(int $index, string $nameInCorrectCasing): void
    {
        $tokens = $this->magicCasingTokens;
        if (null === $tokens) {
            return;
        }

        $tokens[$index] = new Token([T_STRING, $nameInCorrectCasing]);
    }

    public function applyNativeFunctionCasing(Tokens $tokens): void
    {
        $this->nativeFunctionTokens = $tokens;
        $this->nativeFunctionCasingAnalyzer = new FunctionsAnalyzer();
        $this->ensureNativeFunctionNames();

        for ($index = 0, $count = $tokens->count(); $index < $count; ++$index) {
            if (!$this->nativeFunctionCasingAnalyzer->isGlobalFunctionCall($tokens, $index)) {
                continue;
            }

            $this->fixNativeFunctionName($index);
        }
    }

    private function ensureNativeFunctionNames(): void
    {
        if ([] !== $this->nativeFunctionNames && null !== $this->nativeFunctionTokens) {
            return;
        }

        $this->nativeFunctionNames = [];
        $allFunctions = get_defined_functions();
        foreach ($allFunctions['internal'] as $function) {
            $this->nativeFunctionNames[strtolower($function)] = $function;
        }
    }

    private function fixNativeFunctionName(int $index): void
    {
        $tokens = $this->nativeFunctionTokens;
        if (null === $tokens) {
            return;
        }

        $lower = strtolower($tokens[$index]->getContent());
        if (!\array_key_exists($lower, $this->nativeFunctionNames)) {
            return;
        }

        $tokens[$index] = new Token([T_STRING, $this->nativeFunctionNames[$lower]]);
    }

    public function applyMagicConstantCasing(Tokens $tokens): void
    {
        $this->magicCasingTokens = $tokens;
        $this->ensureMagicConstants();

        foreach ($tokens as $index => $token) {
            if ($token->isGivenKind($this->magicConstantTokensList)) {
                $this->fixMagicConstantToken($index);
            }
        }
    }

    private function ensureMagicConstants(): void
    {
        if ([] !== $this->magicConstants && null !== $this->magicCasingTokens) {
            return;
        }

        $this->magicConstants = [
            T_LINE => '__LINE__',
            T_FILE => '__FILE__',
            T_DIR => '__DIR__',
            T_FUNC_C => '__FUNCTION__',
            T_CLASS_C => '__CLASS__',
            T_METHOD_C => '__METHOD__',
            T_NS_C => '__NAMESPACE__',
            CT::T_CLASS_CONSTANT => 'class',
            T_TRAIT_C => '__TRAIT__',
        ];
        $this->magicConstantTokensList = array_keys($this->magicConstants);
    }

    private function fixMagicConstantToken(int $index): void
    {
        $tokens = $this->magicCasingTokens;
        if (null === $tokens) {
            return;
        }

        $token = $tokens[$index];
        if (!isset($this->magicConstants[$token->getId()])) {
            return;
        }

        $tokens[$index] = new Token([$token->getId(), $this->magicConstants[$token->getId()]]);
    }

    /**
     * @return list<int>
     */
    public function getMagicConstantTokenKinds(): array
    {
        $this->ensureMagicConstants();

        return $this->magicConstantTokensList;
    }

    public function applyLowercaseStaticReferenceCasing(Tokens $tokens): void
    {
        $this->staticReferenceTokens = $tokens;
        $this->staticReferenceCandidates = [];

        foreach ($tokens as $index => $token) {
            if (!$token->equalsAny([[T_STRING, 'self'], [T_STATIC, 'static'], [T_STRING, 'parent']], false)) {
                continue;
            }

            $this->staticReferenceCandidates[] = [$index, $token->getContent()];
        }

        foreach ($this->staticReferenceCandidates as [$index, $content]) {
            $this->maybeFixStaticReference($index, $content);
        }
    }

    private function maybeFixStaticReference(int $index, string $content): void
    {
        $tokens = $this->staticReferenceTokens;
        if (null === $tokens) {
            return;
        }

        $newContent = strtolower($content);
        if ($content === $newContent) {
            return;
        }

        if ($this->shouldSkipStaticReferenceNeighbour($index, $newContent)) {
            return;
        }

        $tokens[$index] = new Token([$tokens[$index]->getId(), $newContent]);
    }

    private function shouldSkipStaticReferenceNeighbour(int $index, string $newContent): bool
    {
        $tokens = $this->staticReferenceTokens;
        if (null === $tokens) {
            return true;
        }

        $prevIndex = $tokens->getPrevMeaningfulToken($index);
        if (null === $prevIndex) {
            return true;
        }

        if ($tokens[$prevIndex]->isGivenKind([T_CONST, T_DOUBLE_COLON, T_FUNCTION, T_NAMESPACE, T_NS_SEPARATOR, T_STATIC, T_STRING, CT::T_ARRAY_TYPEHINT, CT::T_DISJUNCTIVE_NORMAL_FORM_TYPE_PARENTHESIS_CLOSE]) || $tokens[$prevIndex]->isObjectOperator()) {
            return true;
        }

        $nextIndex = $tokens->getNextMeaningfulToken($index);
        if (null === $nextIndex) {
            return true;
        }

        if ($tokens[$nextIndex]->isGivenKind([T_FUNCTION, T_NS_SEPARATOR, T_PRIVATE, T_PROTECTED, T_PUBLIC, T_STRING, CT::T_NULLABLE_TYPE])) {
            return true;
        }

        if ('static' === $newContent && $tokens[$nextIndex]->isGivenKind(T_VARIABLE)) {
            return true;
        }

        return $tokens[$prevIndex]->isGivenKind(T_CASE) && !$tokens[$nextIndex]->isGivenKind(T_PAAMAYIM_NEKUDOTAYIM);
    }

    public function applyIntegerLiteralCasing(Tokens $tokens): void
    {
        $this->integerLiteralTokens = $tokens;
        $this->integerLiteralReplacements = [];

        foreach ($tokens as $index => $token) {
            if (!$token->isGivenKind(T_LNUMBER)) {
                continue;
            }

            $this->collectIntegerLiteralReplacement($index, $token->getContent());
        }

        foreach ($this->integerLiteralReplacements as $index => $newContent) {
            $this->applyIntegerLiteralReplacement($index, $newContent);
        }
    }

    private function collectIntegerLiteralReplacement(int $index, string $content): void
    {
        if (null === $this->integerLiteralTokens) {
            return;
        }

        $newContent = Preg::replaceCallback(
            '#^0([boxBOX])([0-9a-fA-F_]+)$#',
            static fn ($matches) => '0'.strtolower($matches[1]).strtoupper($matches[2]),
            $content
        );

        if ($content === $newContent) {
            return;
        }

        $this->integerLiteralReplacements[$index] = $newContent;
    }

    private function applyIntegerLiteralReplacement(int $index, string $newContent): void
    {
        $tokens = $this->integerLiteralTokens;
        if (null === $tokens) {
            return;
        }

        $tokens[$index] = new Token([T_LNUMBER, $newContent]);
    }

    /**
     * @param array<string, list<Token>> $functionsFixMap
     */
    public function applyFunctionToConstantFix(Tokens $tokens, array $functionsFixMap): void
    {
        $this->functionToConstantTokens = $tokens;
        $this->functionToConstantMap = $functionsFixMap;
        $this->nativeFunctionCasingAnalyzer = new FunctionsAnalyzer();

        for ($index = $tokens->count() - 4; $index > 0; --$index) {
            $candidate = $this->getFunctionToConstantCandidate($index);
            if (null === $candidate) {
                continue;
            }

            $this->fixFunctionCallToConstant(
                $index,
                $candidate[0],
                $candidate[1],
                $candidate[2]
            );
        }
    }

    /**
     * @return null|array{int, int, list<Token>}
     */
    private function getFunctionToConstantCandidate(int $index): ?array
    {
        $tokens = $this->functionToConstantTokens;
        if (null === $tokens || !$tokens[$index]->isGivenKind(T_STRING)) {
            return null;
        }

        $lowerContent = strtolower($tokens[$index]->getContent());

        if ('get_class' === $lowerContent) {
            return $this->fixGetClassCall($index);
        }

        if (!isset($this->functionToConstantMap[$lowerContent])) {
            return null;
        }

        if (!$this->nativeFunctionCasingAnalyzer->isGlobalFunctionCall($tokens, $index)) {
            return null;
        }

        $braceOpenIndex = $tokens->getNextMeaningfulToken($index);
        if (null === $braceOpenIndex || !$tokens[$braceOpenIndex]->equals('(')) {
            return null;
        }

        $braceCloseIndex = $tokens->getNextMeaningfulToken($braceOpenIndex);
        if (null === $braceCloseIndex || !$tokens[$braceCloseIndex]->equals(')')) {
            return null;
        }

        return $this->getReplacementTokenClones($lowerContent, $braceOpenIndex, $braceCloseIndex);
    }

    /**
     * @return null|array{int, int, list<Token>}
     */
    private function fixGetClassCall(int $index): ?array
    {
        $tokens = $this->functionToConstantTokens;
        if (null === $tokens) {
            return null;
        }

        if (!isset($this->functionToConstantMap['get_class']) && !isset($this->functionToConstantMap['get_class_this'])) {
            return null;
        }

        if (!$this->nativeFunctionCasingAnalyzer->isGlobalFunctionCall($tokens, $index)) {
            return null;
        }

        $braceOpenIndex = $tokens->getNextMeaningfulToken($index);
        if (null === $braceOpenIndex) {
            return null;
        }

        $braceCloseIndex = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $braceOpenIndex);

        if ($braceCloseIndex === $tokens->getNextMeaningfulToken($braceOpenIndex)) {
            if (isset($this->functionToConstantMap['get_class'])) {
                return $this->getReplacementTokenClones('get_class', $braceOpenIndex, $braceCloseIndex);
            }
        } elseif (isset($this->functionToConstantMap['get_class_this']) && $this->isGetClassThisArgument($braceOpenIndex, $braceCloseIndex)) {
            return $this->getReplacementTokenClones('get_class_this', $braceOpenIndex, $braceCloseIndex);
        }

        return null;
    }

    private function isGetClassThisArgument(int $braceOpenIndex, int $braceCloseIndex): bool
    {
        $tokens = $this->functionToConstantTokens;
        if (null === $tokens) {
            return false;
        }

        $isThis = false;

        for ($i = $braceOpenIndex + 1; $i < $braceCloseIndex; ++$i) {
            if ($tokens[$i]->equalsAny([[T_WHITESPACE], [T_COMMENT], [T_DOC_COMMENT], ')'])) {
                continue;
            }

            if ($tokens[$i]->isGivenKind(T_VARIABLE) && '$this' === strtolower($tokens[$i]->getContent())) {
                $isThis = true;

                continue;
            }

            if (false === $isThis && $tokens[$i]->equals('(')) {
                continue;
            }

            $isThis = false;

            break;
        }

        return $isThis;
    }

    /**
     * @return array{int, int, list<Token>}
     */
    private function getReplacementTokenClones(string $lowerContent, int $braceOpenIndex, int $braceCloseIndex): array
    {
        if (null === $this->functionToConstantTokens) {
            return [$braceOpenIndex, $braceCloseIndex, []];
        }

        $clones = array_map(
            static fn (Token $token): Token => clone $token,
            $this->functionToConstantMap[$lowerContent],
        );

        return [
            $braceOpenIndex,
            $braceCloseIndex,
            $clones,
        ];
    }

    /**
     * @param list<Token> $replacements
     */
    private function fixFunctionCallToConstant(int $index, int $braceOpenIndex, int $braceCloseIndex, array $replacements): void
    {
        $tokens = $this->functionToConstantTokens;
        if (null === $tokens || [] === $replacements) {
            return;
        }

        for ($i = $braceCloseIndex; $i >= $braceOpenIndex; --$i) {
            if ($tokens[$i]->isGivenKind([T_WHITESPACE, T_COMMENT, T_DOC_COMMENT])) {
                continue;
            }

            $tokens->clearTokenAndMergeSurroundingWhitespace($i);
        }

        if (
            $replacements[0]->isGivenKind([T_CLASS_C, T_STATIC])
            || ($replacements[0]->isGivenKind(T_STRING) && 'self' === $replacements[0]->getContent())
        ) {
            $prevIndex = $tokens->getPrevMeaningfulToken($index);
            if (null !== $prevIndex && $tokens[$prevIndex]->isGivenKind(T_NS_SEPARATOR)) {
                $tokens->clearAt($prevIndex);
            }
        }

        $tokens->clearAt($index);
        $tokens->insertAt($index, $replacements);
    }

    public function isClassyInvocation(Tokens $tokens, int $index): bool
    {
        $this->classyInvocationTokens = $tokens;
        $this->ensureClassyInvocationForbiddenPrevKinds();

        $token = $tokens[$index];
        if (!$token->isGivenKind(T_STRING)) {
            throw new \LogicException(sprintf('No T_STRING at given index %d, got "%s".', $index, $tokens[$index]->getName()));
        }

        if ((new TypeAnalysis($token->getContent()))->isReservedType()) {
            return false;
        }

        $next = $tokens->getNextMeaningfulToken($index);
        if (null === $next) {
            return false;
        }

        $nextToken = $tokens[$next];
        if ($nextToken->isGivenKind(T_NS_SEPARATOR)) {
            return false;
        }

        if ($nextToken->isGivenKind([T_DOUBLE_COLON, T_ELLIPSIS, CT::T_TYPE_ALTERNATION, CT::T_TYPE_INTERSECTION, T_VARIABLE])) {
            return true;
        }

        return $this->isClassyInvocationFromPreviousToken($index, $next, $nextToken);
    }

    private function ensureClassyInvocationForbiddenPrevKinds(): void
    {
        if ([] !== $this->classyInvocationForbiddenPrevKinds && null !== $this->classyInvocationTokens) {
            return;
        }

        $this->classyInvocationForbiddenPrevKinds = [
            T_EXTENDS,
            T_INSTANCEOF,
            T_INSTEADOF,
            T_IMPLEMENTS,
            T_NEW,
            CT::T_NULLABLE_TYPE,
            CT::T_TYPE_ALTERNATION,
            CT::T_TYPE_INTERSECTION,
            CT::T_TYPE_COLON,
            CT::T_USE_TRAIT,
        ];
    }

    private function isClassyInvocationFromPreviousToken(int $index, int $next, Token $nextToken): bool
    {
        $tokens = $this->classyInvocationTokens;
        if (null === $tokens) {
            return false;
        }

